  var PROLOGUE = {
    cine: [
      { at: "gate", shot: "wide", sec: 4, caption: "\uC131\uCC44\uC758 \uC5F0\uB300\uAE30\uB294 \uC774\uB807\uAC8C \uC801\uB294\uB2E4." },
      { at: "gate", shot: "rise", sec: 6, caption: "\uBC31 \uB144 \uC804 \uACA8\uC6B8, \uC5D0\uB974\uD558\uC784\uC758 \uC5EC\uC12F \uAE43\uBC1C\uC774 \uC11C\uB85C\uC758 \uC131\uC744 \uACA8\uB204\uC5C8\uB2E4. \uB2E4\uC12F \uAE43\uBC1C\uC774 \uC0AC\uC790\uC758 \uC131 \uBCA8\uB85C\uC2A4\uB97C \uC5D0\uC6CC\uC30C\uB2E4." },
      { at: "altar", shot: "orbit", sec: 6, caption: "\uADF8 \uBC24 \uBD81\uCABD \uC81C\uB2E8\uC5D0\uC11C \uBD88\uC774 \uB0B4\uB824\uC640 \uB4E4\uD310\uC758 \uAD70\uC138\uB97C \uC0BC\uCF30\uB2E4. \uC5F0\uB300\uAE30\uB294 \uADF8 \uBD88\uC744 \uC5FC\uC625\uC758 \uAD70\uC8FC \uBC1C\uCE74\uB974\uB77C \uBD80\uB978\uB2E4." },
      { at: "altar", shot: "rise", sec: 6, caption: "\uC0AC\uC790\uC655\uC740 \uC81C \uBAA9\uC228\uC744 \uAC12\uC73C\uB85C \uADF8 \uBD88\uC744 \uC81C\uB2E8\uC5D0 \uBB36\uC5C8\uB2E4. \uADF8 \uB4A4\uB85C \uC5D0\uB974\uD558\uC784\uC5D0 \uC655\uC740 \uC5C6\uACE0, \uC5EC\uC12F \uBB38\uD30C\uAC00 \uAE43\uBC1C\uC744 \uB098\uB220 \uB4E4\uC5C8\uB2E4." },
      { at: "plaza", shot: "wide", sec: 5, caption: '\uC0AC\uC790\uC758 \uAE30\uC0AC\uB4E4\uC740 \uB9F9\uC138\uD588\uB2E4. "\uBD88\uC774 \uBD80\uB974\uB294 \uB0A0, \uC0AC\uC790\uB294 \uC81C \uBC1C\uB85C \uAC04\uB2E4."' },
      { at: "plaza", shot: "close", sec: 5, caption: "\uC5F0\uB300\uAE30\uB294, \uADF8\uB807\uAC8C \uC801\uB294\uB2E4." }
    ],
    lines: [
      ["liena", "@ \uB9DE\uC9C0? \uC740\uC0AC\uC790 \uBD80\uBB38\uC8FC \uB9AC\uC5D0\uB098\uC57C. \uB0B4\uAC00 \uBD81\uBB38\uAE4C\uC9C0 \uB9C8\uC911 \uB098\uC624\uB294 \uC77C\uC740 \uB4DC\uBB34\uB2C8\uAE4C \uC601\uAD11\uC73C\uB85C \uC54C\uC544."],
      ["liena", "\uBB38\uC8FC \uC790\uB9AC\uB294 \uC2ED \uB144\uC9F8 \uBE44\uC5B4 \uC788\uC5B4. \uB204\uAC00 \uC549\uC744 \uC758\uC790\uAC00 \uC544\uB2C8\uB2C8\uAE4C \uAD81\uAE08\uD574\uD558\uC9C0\uB294 \uB9C8. \uBA85\uBD80\uBD80\uD130 \uC4F0\uC790."],
      ["orben", "\uC131\uCC44 \uAE30\uB85D\uAD00 \uC624\uB974\uBCA4\uC77C\uC138. @\u2026 \uD68D\uC774 \uACE0\uC6B4 \uC774\uB984\uC774\uAD70. \uD55C \uC790\uB3C4 \uD2C0\uB9AC\uC9C0 \uC54A\uAC8C \uC801\uC5B4 \uB450\uACA0\uB124."],
      ["nar", "\uAE43\uD39C\uC774 \uB450\uAEBC\uC6B4 \uBA85\uBD80 \uC704\uB97C \uC9C0\uB098\uAC04\uB2E4. \uB178\uC778\uC740 \uC774\uB984 \uC606\uC5D0 \uC1E0\uB3C4\uC7A5\uC744 \uB20C\uB800\uB2E4. \uC0AC\uC790\uAC00 \uAC70\uAFB8\uB85C \uCC0D\uD78C \uAC83\uB3C4 \uAC19\uB2E4."],
      ["orben", "\uC774\uC81C \uC790\uB124\uB3C4 \uC0AC\uC790\uC758 \uC774\uB984 \uC544\uB798 \uC788\uB124. \uC131\uCC44\uB294 \uC81C \uC0AC\uB78C\uC744 \uC78A\uB294 \uBC95\uC774 \uC5C6\uC9C0."],
      ["tobin", "\uC624\uB298 \uC785\uB2E8\uD55C \uC0AC\uB78C \uB610 \uC788\uC5B4? \uB098\uB3C4 \uC624\uB298\uC774\uC57C! \uC798 \uBD80\uD0C1\uD574!"],
      ["liena", "\uC800 \uC2DC\uB044\uB7EC\uC6B4 \uC560\uB294 \uD1A0\uBE48. \uB124 \uC785\uB2E8 \uB3D9\uAE30\uC57C. \uC790, \uBE48\uC190\uC73C\uB85C \uC232\uC5D0 \uB098\uAC08 \uC21C \uC5C6\uC9C0. \uC7A1\uD654\uC810\uBD80\uD130 \uB4E4\uB7EC."],
      ["liena", "\uAE38\uC740 \uC678\uC6B8 \uD544\uC694 \uC5C6\uC5B4. \uC758\uB8B0\uCC3D\uC5D0\uC11C [\uC774\uC57C\uAE30]\uB9CC \uB204\uB974\uBA74 \uBC1C\uC774 \uBA3C\uC800 \uAC00\uB2C8\uAE4C."]
    ]
  };
