    orc_warrior: { name: "\uC624\uD06C \uC804\uC0AC", level: 16, hp: 880, atk: 44, exp: 62, gold: [26, 55], speed: 3.6, range: 2.4, r: 0.85, portrait: "ui/portrait_orc.jpg", sfx: "orc_grunt" },
