  function randomName(rng2) {
    const r = typeof rng2 === "function" ? rng2() : Math.random();
    return BOT_NAMES[Math.min(BOT_NAMES.length - 1, Math.floor(r * BOT_NAMES.length))];
  }
  function findGuild(g) {
    if (g == null || g === "") return null;
    if (typeof g === "object") return findGuild(g.id != null ? g.id : g.name);
    if (typeof g === "number") return GUILDS2[g] || null;
    for (let i = 0; i < GUILDS2.length; i++) {
      if (GUILDS2[i].id === g || GUILDS2[i].name === g) return GUILDS2[i];
    }
    return null;
  }
  function guildName(g) {
    const f2 = findGuild(g);
    if (f2) return f2.name;
    if (typeof g === "string") return g;
    if (g && typeof g === "object" && typeof g.name === "string") return g.name;
    return "";
  }
  function pickNames(n, rng2) {
    const r = typeof rng2 === "function" ? rng2 : Math.random;
    const a = BOT_NAMES.slice();
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(r() * (i + 1));
      const t = a[i];
      a[i] = a[j];
      a[j] = t;
    }
    return a.slice(0, Math.max(0, Math.min(n, a.length)));
  }

